n = int(input())
a = input().split()
cnt = {}
for x in a:
    cnt[int(x)] = cnt.get(int(x), 0) + 1
print(sum(1 for v in cnt.values() if v == 2))

n, t = map(int, input().split())
a = list(map(int, input().split()))
first = {}
ans = '-1'
for j, x in enumerate(a):
    if t - x in first:
        ans = f"{first[t - x]} {j}"
        break
    if x not in first:
        first[x] = j
print(ans)

n, k = map(int, input().split())
a = list(map(int, input().split()))
cnt = {}
for x in a:
    cnt[x] = cnt.get(x, 0) + 1
if k == 0:
    print(sum(1 for v in cnt.values() if v >= 2))
else:
    print(sum(1 for x in cnt if x + k in cnt))

n = int(input())
s = set(map(int, input().split()))
best = 0
for x in s:
    if x - 1 not in s:
        y = x
        while y + 1 in s:
            y += 1
        best = max(best, y - x + 1)
print(best)
